                 } else {
                     let gone = stands.remove(j);
                     // R4805000: a later splash meets its body without Taunt, or nothing.
                     if w.splash_trample_read {
                         bystanders.insert(gone.unit.id.clone(), left_behind(state, &gone, exiling));
